// primeni detaljne korake i izdvoj savet
for (const r of RECIPES) {
  const v = STEPS[r.id]; if (!v) continue;
  const parts = v.split('|').map((x) => x.trim()).filter(Boolean);
  r.tip = parts.filter((x) => x.startsWith('💡')).map((x) => x.replace(/^💡\s*/, '')).join(' ');
  r.steps = parts.filter((x) => !x.startsWith('💡'));
}
// minuti u koraku (npr. „kuvaj 25–30 min“, „1,5 h“) – za tajmer
function stepMinutes(t) {
  let m = t.match(/(\d+(?:,\d+)?)\s*(?:–\s*(\d+(?:,\d+)?))?\s*h\b/);
  if (m) return Math.round(parseFloat((m[2] || m[1]).replace(',', '.')) * 60);
  m = t.match(/(\d+)\s*(?:–\s*(\d+))?\s*min\b/);
  return m ? +(m[2] || m[1]) : 0;
}
